// Input: expects the Webhook output JSON to be accessible
// Adjust if needed for your workflow
const link = $('Webhook').first().json.body.content['Odkaz na fotky'];

let id = null;

// Try different Google Drive link formats
if (link) {
  // Match file/d/<ID>
  let match = link.match(/\/file\/d\/([^/]+)/);
  if (match) {
    id = match[1];
  }

  // Match folders/<ID>
  if (!id) {
    match = link.match(/\/folders\/([^/?]+)/);
    if (match) {
      id = match[1];
    }
  }

  // Match open?id=<ID>
  if (!id) {
    match = link.match(/[?&]id=([^&]+)/);
    if (match) {
      id = match[1];
    }
  }
}

// Return as node output
return [
  {
    json: {
      driveId: id
    }
  }
];

